#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true
STAMP="$(date +%Y%m%d_%H%M%S)"; BK="$HOME/companyos/.companyos_backups/autonomous_diagnostics_$STAMP"; mkdir -p "$BK"
cp companyos/runtime/service_supervisor.py "$BK/" 2>/dev/null || true
echo ""|base64 -d > companyos/runtime/autonomous_diagnostics.py
echo ""|base64 -d > scripts/companyos_diagctl; chmod +x scripts/companyos_diagctl
mkdir -p tests; echo ""|base64 -d > tests/test_autonomous_diagnostics.py
echo ""|base64 -d > "$PREFIX/tmp/cos_diag_patch.py"; echo "V1_FRAGILE_PATCH=SKIPPED"; rm -f "$PREFIX/tmp/cos_diag_patch.py"
echo "" | base64 -d > "$PREFIX/tmp/cos_diag_patch_v2.py"
python "$PREFIX/tmp/cos_diag_patch_v2.py"
rm -f "$PREFIX/tmp/cos_diag_patch_v2.py"
python -m py_compile companyos/runtime/service_supervisor.py
echo "SUPERVISOR_SYNTAX_V2=PASS"
python -m py_compile companyos/runtime/autonomous_diagnostics.py companyos/runtime/service_supervisor.py
python -m unittest tests.test_autonomous_diagnostics -v
scripts/companyos_diagctl once
git add companyos/runtime/autonomous_diagnostics.py companyos/runtime/service_supervisor.py scripts/companyos_diagctl tests/test_autonomous_diagnostics.py
git diff --cached --quiet || git commit -m "Add autonomous diagnosis and safe self-healing"
BRANCH="$(git branch --show-current)"; [ -n "$BRANCH" ] && git push origin "$BRANCH" || true
scripts/companyosctl restart || true; sleep 8
echo "===== DIAGNOSTICS ====="; scripts/companyos_diagctl status
echo "===== SERVICES ====="; scripts/companyosctl status || true
echo "BACKUP=$BK"
echo "COMPANYOS_AUTONOMOUS_DIAGNOSTICS_V2=PASS"
